-- Model: Xenova/bge-small-zh-v1.5
-- Model revision: 75c43b069aac4d136ba6bc1122f995fedcfd2781
-- Model documentation: https://huggingface.co/Xenova/bge-small-zh-v1.5
-- Supabase documentation: https://supabase.com/docs/guides/ai/vector-columns
-- Base model: BAAI/bge-small-zh-v1.5; ONNX INT8 export: onnx/model_int8.onnx.
-- Model file SHA256: b9837c19ce154ff0726d398ee77abbc03a7faf0476c6f93016c84e531be7ebb5
-- Input: question + newline + answer. Dimension: 512. CLS pooling; L2 normalized.
-- No document instruction prefix; all inputs fit within 512 tokens without truncation.
-- Query embeddings must use the same model revision, ONNX variant, CLS pooling
-- and L2 normalization. Optional query prefix: 为这个句子生成表示以用于检索相关文章：
-- Run this file in the Supabase SQL Editor as the database owner.
-- Re-running updates identical question/answer pairs without deleting other data.
-- RLS is enabled; client access requires policies appropriate for your application.

BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions, pg_catalog;

CREATE TABLE IF NOT EXISTS public.qa (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question text NOT NULL,
    answer text NOT NULL,
    source_url text,
    embedding vector(512) NOT NULL,
    CONSTRAINT qa_question_answer_key UNIQUE (question, answer)
);

ALTER TABLE public.qa ENABLE ROW LEVEL SECURITY;
COMMENT ON COLUMN public.qa.embedding IS 'Xenova/bge-small-zh-v1.5@75c43b069aac4d136ba6bc1122f995fedcfd2781; onnx/model_int8.onnx; 512 dimensions; question + newline + answer; CLS pooling; L2 normalized';

ON CONFLICT (question, answer) DO UPDATE SET
    source_url = EXCLUDED.source_url,
    embedding = EXCLUDED.embedding;

COMMIT;
